  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <main id="maincontent" tabindex="-1">
      <section class="support-card" aria-labelledby="support-heading">
        <h1 id="support-heading">Contact support</h1>
        <p class="intro">
          Share your details and our support team will follow up as soon as possible.
        </p>
        <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-errormessage="full-name-error"
            />
            <p id="full-name-error" class="error-message" hidden></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              inputmode="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
              aria-errormessage="email-error"
            />
            <p id="email-error" class="error-message" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
              aria-errormessage="phone-error"
            />
            <p id="phone-help" class="helper-text">
              Optional. Enter digits with spaces, dashes, or parentheses, for example
              +1 (555) 123-4567.
            </p>
            <p id="phone-error" class="error-message" hidden></p>
          </div>

          <button type="submit">Send request</button>
          <p id="form-status" class="status-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusMessage = document.getElementById("form-status");

      const fields = [
        {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            const trimmed = value.trim();

            if (!trimmed) {
              return "Error: Enter your full name.";
            }

            if (trimmed.length < 2 || !trimmed.includes(" ")) {
              return "Error: Enter your first and last name.";
            }

            return "";
          },
        },
        {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            const trimmed = value.trim();
            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (!trimmed) {
              return "Error: Enter your email address.";
            }

            if (!emailPattern.test(trimmed)) {
              return "Error: Enter a valid email address, like name@example.com.";
            }

            return "";
          },
        },
        {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            const trimmed = value.trim();
            const phonePattern = /^\+?[\d\s().-]{7,20}$/;

            if (!trimmed) {
              return "";
            }

            if (!phonePattern.test(trimmed)) {
              return "Error: Enter a phone number using digits and common separators only.";
            }

            return "";
          },
        },
      ];

      function showFieldError(field, message) {
        field.input.setAttribute("aria-invalid", "true");
        field.error.textContent = message;
        field.error.hidden = false;
      }

      function clearFieldError(field) {
        field.input.removeAttribute("aria-invalid");
        field.error.textContent = "";
        field.error.hidden = true;
      }

      function validateField(field) {
        const message = field.validate(field.input.value);

        if (message) {
          showFieldError(field, message);
          return false;
        }

        clearFieldError(field);
        return true;
      }

      fields.forEach((field) => {
        field.input.addEventListener("blur", () => {
          validateField(field);
        });

        field.input.addEventListener("input", () => {
          if (field.input.hasAttribute("aria-invalid")) {
            validateField(field);
          }
          statusMessage.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusMessage.textContent = "";

        const invalidField = fields.find((field) => !validateField(field));

        if (invalidField) {
          invalidField.input.focus();
          return;
        }

        statusMessage.textContent = "Your support request is ready to send.";
        form.reset();
        fields.forEach(clearFieldError);
        fields[0].input.focus();
      });
    </script>
