 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         --color-bg: #0b1120;
         --color-panel: #111a2e;
         --color-panel-alt: #16213a;
         --color-text: #f3f7ff;
         --color-muted-text: #b7c2d8;
         --color-border: #3a4a6a;
         --color-focus: #7dd3fc;
         --color-danger: #fda4af;
         --color-success: #86efac;
         --color-button: #38bdf8;
         --color-button-text: #08111f;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Arial, Helvetica, sans-serif;
         background:
           radial-gradient(circle at top, #1d2b4c 0%, var(--color-bg) 42%),
           var(--color-bg);
         color: var(--color-text);
         line-height: 1.5;
       }

       .skip-link {
         position: absolute;
         top: 0;
         left: 0;
         transform: translateY(-120%);
         padding: 0.75rem 1rem;
         background: var(--color-text);
         color: var(--color-bg);
         font-weight: 700;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--color-focus);
         outline-offset: 2px;
       }

       main {
         display: grid;
         place-items: center;
         min-height: 100vh;
         padding: 2rem 1rem;
       }

       .support-card {
         width: min(100%, 38rem);
         padding: 2rem;
         border: 1px solid var(--color-border);
         border-radius: 1.25rem;
         background: linear-gradient(180deg, var(--color-panel-alt), var(--color-panel));
         box-shadow: 0 1.5rem 3rem rgba(0, 0, 0, 0.35);
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(1.9rem, 4vw, 2.5rem);
         line-height: 1.1;
       }

       .intro,
       .required-note,
       .helper-text {
         color: var(--color-muted-text);
       }

       .intro {
         margin: 0 0 1.5rem;
       }

       .required-note {
         margin: 0 0 1rem;
         font-size: 0.95rem;
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 700;
       }

       .required-mark {
         color: var(--color-danger);
       }

       input {
         width: 100%;
         padding: 0.85rem 1rem;
         border: 1px solid var(--color-border);
         border-radius: 0.85rem;
         background: #0d172b;
         color: var(--color-text);
         font: inherit;
       }

       input::placeholder {
         color: #95a3bf;
       }

       input:focus,
       button:focus {
         outline: 3px solid var(--color-focus);
         outline-offset: 2px;
         box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.2);
       }

       input[aria-invalid="true"] {
         border-color: var(--color-danger);
       }

       .helper-text,
       .error-message,
       .status-message {
         margin: 0;
         font-size: 0.95rem;
       }

       .error-message {
         color: var(--color-danger);
       }

       .status-message {
         min-height: 1.5rem;
