       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.25rem;
         font: inherit;
         font-weight: 700;
         color: var(--color-button-text);
         background: linear-gradient(180deg, #7dd3fc, var(--color-button));
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.05);
       }

       button:active {
         transform: translateY(1px);
       }

       [hidden] {
         display: none;
